import 'server-only';

import { activeAccessToken, clientUserAgentHeader, gatewayUrl } from '@/server/gateway';
import { getSession, isElevated, type SessionPayload } from '@/server/session';
import { can, type PermissionRule } from '@/shared/auth/ability';

import adminSpec from './openapi.admin.json';
import businessSpec from './openapi.business.json';

/**
 * TASK-783 — server-side delivery of the developer-portal OpenAPI specs.
 *
 * Two projections, generated by `pnpm api:portal` from the gateway's committed
 * `openapi.json` × `route-manifest.json`:
 *
 * | Plane | Contents | Required |
 * |---|---|---|
 * | `business` | only routes a tenant credential can reach | `read:ApiDocumentation` |
 * | `admin` | every documented route, including `/api/v1/admin/**` | `manage:ApiDocumentation` (in practice `manage:all`) |
 *
 * ## Why the split is enforced HERE and not in the UI
 *
 * The business projection does not merely hide administration routes — it does
 * not contain them. A payload is a leak the moment it is served, whatever the
 * client chooses to render, so the audience decision has to happen before the
 * bytes leave the server. That is also why the two projections are separate
 * files rather than one document filtered per request: there is no code path
 * in which an under-privileged caller holds the full document in memory.
 *
 * ## Why abilities are fetched from the gateway
 *
 * The session cookie carries the user's identity and tokens, NOT their CASL
 * rules — `src/shared/auth/ability.ts` hydrates those from the gateway for the
 * client. Trusting a cookie-carried ability list would make the console its own
 * authorization authority, which it is not: the gateway is. So this module asks
 * the gateway the same question the client asks, with the caller's own token,
 * and fails CLOSED on any error.
 */

export type SpecPlane = 'business' | 'admin';

/** The two committed projections, as plain JSON imported into the server bundle. */
const SPECS: Record<SpecPlane, unknown> = {
  business: businessSpec,
  admin: adminSpec,
};

export function isSpecPlane(value: string): value is SpecPlane {
  return value === 'business' || value === 'admin';
}

interface PermissionCheckResponse {
  permissions?: PermissionRule[];
}

/**
 * The caller's effective CASL rules, straight from the gateway.
 *
 * Returns `null` when the gateway cannot be asked or refuses. Every caller
 * below treats `null` as "no access" — an unreachable authority must never
 * read as an unrestricted one.
 */
export async function fetchPermissionRules(session: SessionPayload, request?: Request): Promise<PermissionRule[] | null> {
  const headers = new Headers({
    authorization: `Bearer ${activeAccessToken(session)}`,
    ...(request ? clientUserAgentHeader(request) : {}),
  });
  if (session.workingTenantId && isElevated(session.user)) {
    headers.set('x-tenant-id', session.workingTenantId);
  }

  try {
    const response = await fetch(gatewayUrl('users/me/permission-checks'), {
      method: 'POST',
      headers,
      cache: 'no-store',
      redirect: 'manual',
    });
    if (!response.ok) return null;

    const body = (await response.json()) as PermissionCheckResponse;
    return Array.isArray(body.permissions) ? body.permissions : null;
  } catch {
    return null;
  }
}

export interface DocsAccess {
  /** May open the portal at all. */
  canRead: boolean;
  /** May receive the administration projection. */
  canReadAdminPlane: boolean;
}

export const NO_DOCS_ACCESS: DocsAccess = { canRead: false, canReadAdminPlane: false };

/** Resolve both gates from a rule set. `manage:all` satisfies both via CASL. */
export function docsAccessFromRules(rules: readonly PermissionRule[] | null): DocsAccess {
  if (!rules) return NO_DOCS_ACCESS;

  return {
    canRead: can(rules, 'read', 'ApiDocumentation'),
    canReadAdminPlane: can(rules, 'manage', 'ApiDocumentation'),
  };
}

/** The current caller's documentation access, or {@link NO_DOCS_ACCESS} when unauthenticated. */
export async function resolveDocsAccess(request?: Request): Promise<DocsAccess> {
  const session = await getSession();
  if (!session) return NO_DOCS_ACCESS;

  return docsAccessFromRules(await fetchPermissionRules(session, request));
}

/**
 * The projection this caller is entitled to for the plane they asked for.
 *
 * `null` means "do not serve anything" — the caller lacks the ability, and the
 * route handler turns that into a 403 without disclosing which projection
 * exists.
 */
export function specForPlane(plane: SpecPlane, access: DocsAccess): unknown | null {
  if (!access.canRead) return null;
  if (plane === 'admin' && !access.canReadAdminPlane) return null;
  return SPECS[plane];
}
